/// Drives Chain iteration by storing either a linked next error or a buffered iterator.
/// Allows Chain::next and size_hint to walk the error cause chain lazily.
#[derive(Clone)]
pub(crate) enum ChainState<'a> {
    Linked {
        next: Option<&'a (dyn crate::StdError + 'static)>,
    },
    #[cfg(any(feature = "std", not(anyhow_no_core_error)))]
    Buffered {
        rest: alloc::vec::IntoIter<&'a (dyn crate::StdError + 'static)>,
    },
}

/// Enables attaching context while keeping the underlying error's TypeId visible to downcast.
pub trait StdError {
    fn ext_context<C>(self, context: C) -> Error
    where
        C: Display + Send + Sync + 'static;
}

